@startuml

class Game {
  + id : string
}

class Player {
  + id : string
}

class Deck {
  + id : string
}

class Card {
  + id : string
  + compareHeight(other: Card) : string
}

enum Suit {
  DIAMONDS
  HEARTS
  SPADES
  CLUBS
}

class ScoringTable {
  + id : string
}

class Round {
  + id : string
  + pointValue : int
}

class JackRound extends Round {
}

class SoloRound extends Round {
  + soloType : SoloType
}

class MandatorySoloRound extends SoloRound {
}

enum SoloType {
  TRUMP
  JACK
  QUEEN
}

class SoloPlayer {
  + id : string
}

Game "1" -- "4" Player
Game "1" -- "1" Deck
Game "1" -- "1" ScoringTable
ScoringTable "1" -- "*" Round
Round "1" -- "*" Player : winning players
Round "1" -- "0..1" SoloPlayer : solo player

Deck "1" -- "0..48" Card
Card "1" -- "1" Suit

@enduml

